class MapSum {
    private final Map<String,Integer> values=new HashMap<>(),prefixSums=new HashMap<>();
    public MapSum(){
    }
    public void insert(String key,int val){
        int delta=val-values.getOrDefault(key,0);
        values.put(key,val);
        for(int end=1;end<=key.length();end++){
            String prefix=key.substring(0,end);
            prefixSums.put(prefix,prefixSums.getOrDefault(prefix,0)+delta);
        }
    }
    public int sum(String prefix){
        return prefixSums.getOrDefault(prefix,0);
    }
}

code.kotlin:
class MapSum {
    private val values=hashMapOf<String,Int>();
    private val prefixSums=hashMapOf<String,Int>();
    fun insert(key:String,`val`:Int){
        val delta=`val`-(values[key]?:0);
        values[key]=`val`;
        for(end in 1..key.length){
            val prefix=key.substring(0,end);
            prefixSums[prefix]=(prefixSums[prefix]?:0)+delta
        }
    };
    fun sum(prefix:String):Int=prefixSums[prefix]?:0
}

code.cpp:
class MapSum {
    unordered_map<string,int> values,prefixSums;
    public:MapSum(){
    }
    void insert(string key,int val){
        int delta=val-values[key];
        values[key]=val;
        string prefix;
        for(char c:key){
            prefix+=c;
            prefixSums[prefix]+=delta;
        }
    }
    int sum(string prefix){
        return prefixSums[prefix];
    }
};
